package io.ahad.rechnungflow.testing;
import io.ahad.rechnungflow.core.*;import io.ahad.rechnungflow.workflow.*;import io.ahad.rechnungflow.ingest.*;
import java.util.*;import java.nio.charset.StandardCharsets;import java.util.zip.*;import java.io.*;
import static io.ahad.rechnungflow.testing.TestKit.*;
public final class WorkflowTest {
    private static final String GOOD="01-ubl-office.xml",HIGH="02-ubl-machinery.xml";
    @FunctionalInterface interface Case{void run(Fixtures f)throws Exception;}
    static void test(TestKit t,String name,Case c){t.test(name,()->{try(Fixtures f=new Fixtures()){c.run(f);}});}
    static String id(Map<String,Object>m){return Values.text(m,"id");}
    public static void main(String[]args)throws Exception{
        TestKit t=new TestKit("workflow");
        test(t,"Intake preserves byte-identical original",f->{byte[]b=Fixtures.xml(GOOD);String id=f.intakeBytes(b,f.a("intake"));yes(Arrays.equals(b,f.service.original(f.a("admin"),id)));eq(Crypto.sha(b),Values.text(f.get(id),"sha256"));});
        test(t,"Demo explicitly has no official pass",f->{String id=f.intake(GOOD);eq("REVIEW",Values.text(f.get(id),"stage"));eq("UNAVAILABLE",Values.text(Json.map(Json.map(f.get(id),"validation"),"official"),"status"));});
        test(t,"Malformed input stored as exception without extracted data",f->{String id=f.intake("11-xxe.xml");eq("EXCEPTION",Values.text(f.get(id),"stage"));yes(Json.map(f.get(id),"data").isEmpty());});
        test(t,"Incorrect totals route to exception",f->eq("EXCEPTION",Values.text(f.get(f.intake("05-ubl-bad-total.xml")),"stage")));
        test(t,"Intake idempotency replay same result",f->{byte[]b=Fixtures.xml(GOOD);var a=f.service.intake(f.a("intake"),b,"a.xml","same-key-123",null);var next=f.service.intake(f.a("intake"),b,"b.xml","same-key-123",null);eq(id(a),id(next));yes(Json.bool(next,"replayed",false));});
        test(t,"Idempotency rejects changed content",f->{f.service.intake(f.a("intake"),Fixtures.xml(GOOD),"a","same-key-123",null);error("IDEMPOTENCY_CONFLICT",()->f.service.intake(f.a("intake"),Fixtures.xml(HIGH),"a","same-key-123",null));});
        test(t,"Exact duplicate returns existing invoice",f->{String id=f.intake(GOOD);var r=f.service.intake(f.a("intake"),Fixtures.xml(GOOD),"different.xml",Values.id(),null);eq(id,id(r));yes(Json.bool(r,"duplicate",false));eq(1,Json.integer(f.service.list(f.a("admin"),null,null,0,25),"total",0));});
        test(t,"Semantic duplicate blocks both cases",f->{String id=f.ready(GOOD);f.intakeBytes(Fixtures.changed(GOOD,"Fictional demonstration","Changed fictional demonstration"),f.a("intake"));yes(Json.list(f.get(id),"blockers").contains("DUPLICATE_BUSINESS"));});
        test(t,"Rejecting semantic duplicate unblocks remaining",f->{String id=f.ready(GOOD),second=f.intakeBytes(Fixtures.changed(GOOD,"Fictional demonstration","Changed fictional demonstration"),f.a("intake"));f.service.reject(f.a("reviewer"),second,f.version(second,"reason","Duplicate"));yes(!Json.list(f.get(id),"blockers").contains("DUPLICATE_BUSINESS"));});
        test(t,"Correction links and supersedes original",f->{String old=f.intake("05-ubl-bad-total.xml");String newer=id(f.service.intake(f.a("intake"),Fixtures.xml("09-ubl-corrected.xml"),"correction.xml",Values.id(),old));eq("SUPERSEDED",Values.text(f.get(old),"stage"));eq(old,Values.text(f.get(newer),"supersedes"));yes(Arrays.equals(Fixtures.xml("05-ubl-bad-total.xml"),f.service.original(f.a("admin"),old)));});
        test(t,"Approved invoice cannot be superseded",f->{String id=f.approved(GOOD);error("CORRECTION_NOT_ALLOWED",()->f.service.intake(f.a("intake"),Fixtures.xml(HIGH),"c.xml",Values.id(),id));});
        test(t,"Intake key mandatory",f->error("IDEMPOTENCY_KEY_REQUIRED",()->f.service.intake(f.a("intake"),Fixtures.xml(GOOD),"a",null,null)));
        test(t,"Unsafe idempotency characters rejected",f->error("IDEMPOTENCY_KEY_REQUIRED",()->f.service.intake(f.a("intake"),Fixtures.xml(GOOD),"a","injection\r\n",null)));
        test(t,"Read-only actor cannot upload",f->error("FORBIDDEN",()->f.intakeBytes(Fixtures.xml(GOOD),f.a("auditor"))));
        test(t,"Cross-tenant invoice hidden",f->{String id=f.intake(GOOD);Actor other=new Actor("x","other","Other",Set.of("ADMIN"),false);error("NOT_FOUND",()->f.service.get(other,id));error("NOT_FOUND",()->f.service.original(other,id));});
        test(t,"API key cannot read another intake actor case",f->{String id=f.intake(GOOD);error("NOT_FOUND",()->f.service.get(new Actor("key:x","test","API",Set.of("INTAKE"),true),id));});
        test(t,"Pagination size enforced",f->error("INVALID_PAGINATION",()->f.service.list(f.a("admin"),null,null,0,101)));
        test(t,"Pagination negative page enforced",f->error("INVALID_PAGINATION",()->f.service.list(f.a("admin"),null,null,-1,25)));
        test(t,"Search finds invoice by number",f->{f.intake(GOOD);eq(1,Json.integer(f.service.list(f.a("admin"),"1001",null,0,25),"total",0));eq(0,Json.integer(f.service.list(f.a("admin"),"nonexistent",null,0,25),"total",9));});
        test(t,"Unknown supplier blocks review",f->{String id=f.intake(GOOD);error("SUPPLIER_NOT_FOUND",()->f.review(id));});
        test(t,"Supplier identity uniqueness",f->{f.supplier(GOOD);var d=new InvoiceParser().parse(Fixtures.xml(GOOD));error("SUPPLIER_EXISTS",()->f.service.createSupplier(f.a("reviewer"),Values.map("name","Duplicate","identity",InvoiceService.sellerKey(d),"iban",d.get("iban"))));});
        test(t,"Supplier creator cannot verify own bank data",f->{var s=f.service.createSupplier(f.a("admin"),Values.map("name","Supplier","identity","taxId:DE222333444","iban",""));error("SEPARATION_OF_DUTIES",()->f.service.verifySupplier(f.a("admin"),id(s),Values.map("version",s.get("version"),"reason","Check","confirmedOutOfBand",true)));});
        test(t,"Supplier verification requires external confirmation",f->{var s=f.service.createSupplier(f.a("reviewer"),Values.map("name","Supplier","identity","taxId:DE222333444","iban",""));error("VERIFICATION_CONFIRMATION_REQUIRED",()->f.service.verifySupplier(f.a("approver"),id(s),Values.map("version",s.get("version"),"reason","Check")));});
        test(t,"Invalid bank account rejected",f->error("IBAN_FORMAT",()->f.service.createSupplier(f.a("reviewer"),Values.map("name","S","identity","taxId:DE222333444","iban","DE00"))));
        test(t,"Invoice bank change blocks review",f->{f.supplier(GOOD);String id=f.intake("06-ubl-bank-change.xml");error("BANK_ACCOUNT_CHANGED",()->f.review(id));});
        test(t,"Uploader cannot review even with admin role",f->{f.supplier(GOOD);String id=f.intakeBytes(Fixtures.xml(GOOD),f.a("admin"));error("SEPARATION_OF_DUTIES",()->f.service.review(f.a("admin"),id,f.version(id,"costCenter","100","glAccount","4930","note","Check")));});
        test(t,"Review stores coding and snapshot version",f->{String id=f.ready(GOOD);var i=f.review(id);eq("APPROVAL",Values.text(i,"stage"));eq("IT-100",Values.text(Json.map(i,"metadata"),"costCenter"));eq(2,Json.integer(i,"supplierVersion",0));});
        test(t,"Review requires cost coding",f->{String id=f.ready(GOOD);error("INVALID_INPUT",()->f.service.review(f.a("reviewer"),id,f.version(id,"costCenter","","glAccount","x","note","Check")));});
        test(t,"Review rejects stale version",f->{String id=f.ready(GOOD);error("VERSION_CONFLICT",()->f.service.review(f.a("reviewer"),id,Values.map("version",999,"costCenter","100","glAccount","4930","note","Check")));});
        test(t,"Approver cannot approve before review",f->{String id=f.ready(GOOD);error("INVALID_TRANSITION",()->f.approve(id,"approver"));});
        test(t,"Reviewer cannot approve own review with extra role",f->{String id=f.ready(GOOD);f.review(id);error("SEPARATION_OF_DUTIES",()->f.service.approve(f.withRoles("reviewer","APPROVER"),id,f.version(id,"note","Check")));});
        test(t,"Uploader cannot approve with extra role",f->{String id=f.ready(GOOD);f.review(id);error("SEPARATION_OF_DUTIES",()->f.service.approve(f.withRoles("intake","APPROVER"),id,f.version(id,"note","Check")));});
        test(t,"Low value needs one independent approver",f->{String id=f.ready(GOOD);f.review(id);eq("APPROVED",Values.text(f.approve(id,"approver"),"stage"));});
        test(t,"High value needs two different approvers",f->{String id=f.ready(HIGH);f.review(id);eq("APPROVAL",Values.text(f.approve(id,"approver"),"stage"));eq("APPROVED",Values.text(f.approve(id,"approver2"),"stage"));});
        test(t,"Repeated approver cannot count twice",f->{String id=f.ready(HIGH);f.review(id);f.approve(id,"approver");error("ALREADY_APPROVED",()->f.approve(id,"approver"));});
        test(t,"Approval has optimistic version check",f->{String id=f.ready(GOOD);f.review(id);error("VERSION_CONFLICT",()->f.service.approve(f.a("approver"),id,Values.map("version",1,"note","Check")));});
        test(t,"Rejected invoice cannot proceed",f->{String id=f.ready(GOOD);f.service.reject(f.a("reviewer"),id,f.version(id,"reason","Wrong service"));error("INVALID_TRANSITION",()->f.review(id));});
        test(t,"Rejection reason required",f->{String id=f.intake(GOOD);error("INVALID_INPUT",()->f.service.reject(f.a("reviewer"),id,f.version(id,"reason","")));});
        test(t,"Policy changes do not silently change existing snapshot",f->{String id=f.intake(GOOD);var p=f.service.policy(f.a("admin"));p.put("secondApprovalThreshold","100.00");f.service.updatePolicy(f.a("admin"),p);eq("5000.00",Values.text(Json.map(f.get(id),"policy"),"secondApprovalThreshold"));String next=f.intake(HIGH);eq("100.00",Values.text(Json.map(f.get(next),"policy"),"secondApprovalThreshold"));});
        test(t,"Policy changes require version",f->{var p=f.service.policy(f.a("admin"));p.put("policyVersion",88);error("VERSION_CONFLICT",()->f.service.updatePolicy(f.a("admin"),p));});
        test(t,"Policy cannot lower retention below eight years",f->{var p=f.service.policy(f.a("admin"));p.put("retentionYears",1);error("INVALID_INPUT",()->f.service.updatePolicy(f.a("admin"),p));});
        test(t,"Policy cannot enable demo through update",f->{var p=f.service.policy(f.a("admin"));p.put("mode","STRICT");eq("DEMO",Values.text(f.service.updatePolicy(f.a("admin"),p),"mode"));});
        test(t,"Buyer identity mismatch blocks review",f->{var p=f.service.policy(f.a("admin"));p.put("buyerTaxId","DE000000000");f.service.updatePolicy(f.a("admin"),p);String id=f.ready(GOOD);error("BUYER_IDENTITY_MISMATCH",()->f.review(id));});
        test(t,"Unsupported policy currency blocks review",f->{var p=f.service.policy(f.a("admin"));p.put("currency","USD");f.service.updatePolicy(f.a("admin"),p);String id=f.ready(GOOD);error("CURRENCY_REVIEW_REQUIRED",()->f.review(id));});
        test(t,"Retention hold records actor and reason",f->{String id=f.intake(GOOD);var i=f.service.hold(f.a("finance"),id,f.version(id,"legalHold",true,"reason","Tax examination"));yes(Json.bool(i,"legalHold",false));yes(Values.text(i,"retainUntil").endsWith("-12-31"));});
        test(t,"Auditor cannot change retention hold",f->{String id=f.intake(GOOD);error("FORBIDDEN",()->f.service.hold(f.a("auditor"),id,f.version(id,"reason","Test")));});
        test(t,"Comments preserve literal markup not executable objects",f->{String id=f.intake(GOOD);var i=f.service.comment(f.a("intake"),id,f.version(id,"note","<img src=x onerror=alert(1)>"));eq("<img src=x onerror=alert(1)>",Values.text(Json.object(Json.list(i,"comments").getFirst()),"note"));});
        test(t,"Comment cap enforced",f->{String id=f.intake(GOOD);f.store.write(s->{var i=AuthService.owned(s,"invoices",id,"test");i.put("comments",new ArrayList<>(Collections.nCopies(500,Map.of())));return null;});error("COMMENT_LIMIT",()->f.service.comment(f.a("intake"),id,f.version(id,"note","extra")));});
        test(t,"Read-only actor cannot comment",f->{String id=f.intake(GOOD);error("FORBIDDEN",()->f.service.comment(f.a("auditor"),id,f.version(id,"note","extra")));});
        test(t,"Supplier change invalidates approvals",f->{String id=f.approved(GOOD);var i=f.get(id);var s=Json.object(f.service.suppliers(f.a("admin")).getFirst());f.service.changeSupplier(f.a("reviewer"),id(s),Values.map("version",s.get("version"),"name",s.get("name"),"iban",s.get("iban")));eq("REVIEW",Values.text(f.get(id),"stage"));eq(0,Json.list(f.get(id),"approvals").size());});
        test(t,"Supplier change cancels unclaimed export",f->{String id=f.approved(GOOD);var j=f.queue(id);var s=Json.object(f.service.suppliers(f.a("admin")).getFirst());f.service.changeSupplier(f.a("reviewer"),id(s),Values.map("version",s.get("version"),"name",s.get("name"),"iban",s.get("iban")));eq("CANCELLED",f.store.read(x->Values.text(Json.object(Store.table(x,"jobs").get(id(j))),"status")));});
        test(t,"Uncertain export blocks supplier mutation",f->{String id=f.approved(GOOD);var j=f.queue(id);f.store.write(s->{Json.object(Store.table(s,"jobs").get(id(j))).put("status","UNKNOWN");return null;});var s=Json.object(f.service.suppliers(f.a("admin")).getFirst());error("SUPPLIER_EXPORT_IN_FLIGHT",()->f.service.changeSupplier(f.a("reviewer"),id(s),Values.map("version",s.get("version"),"name",s.get("name"),"iban",s.get("iban"))));});
        test(t,"Export rejects invoice not approved",f->{String id=f.ready(GOOD);error("INVALID_TRANSITION",()->f.queue(id));});
        test(t,"Export requires finance role",f->{String id=f.approved(GOOD);error("FORBIDDEN",()->f.service.export(f.a("approver"),id,f.version(id),Values.id()));});
        test(t,"Export queue changes stage atomically",f->{String id=f.approved(GOOD);var j=f.queue(id);eq("PENDING",Values.text(j,"status"));eq("EXPORT_PENDING",Values.text(f.get(id),"stage"));eq(id(j),Values.text(f.get(id),"exportJobId"));});
        test(t,"Export command replay returns same job",f->{String id=f.approved(GOOD);String k=Values.id();var a=f.service.export(f.a("finance"),id,f.version(id),k);var b=f.service.export(f.a("finance"),id,Values.map("version",1),k);eq(id(a),id(b));});
        test(t,"Demo payload cannot masquerade as real accounting",f->{String id=f.approved(GOOD);var job=f.queue(id);yes(Json.bool(job,"sandbox",false));yes(Json.bool(Json.map(job,"payload"),"sandboxOnly",false));});
        test(t,"Evidence package includes exact original and manifest",f->{String id=f.intake(GOOD);var names=new HashSet<String>();try(var z=new ZipInputStream(new ByteArrayInputStream(f.service.evidence(f.a("auditor"),id)))){ZipEntry e;while((e=z.getNextEntry())!=null){names.add(e.getName());if(e.getName().equals("original.xml"))yes(Arrays.equals(Fixtures.xml(GOOD),z.readAllBytes()));}}eq(Set.of("original.xml","case.json","manifest.json"),names);});
        test(t,"Intake actor cannot extract whole evidence bundle",f->{String id=f.intake(GOOD);error("FORBIDDEN",()->f.service.evidence(f.a("intake"),id));});
        test(t,"CSV export neutralizes invoice number formula",f->{f.intakeBytes(Fixtures.changed(GOOD,"NW-2026-1001","=HYPERLINK(test)"),f.a("intake"));yes(new String(f.service.csv(f.a("finance")),StandardCharsets.UTF_8).contains("'=HYPERLINK"));});
        test(t,"Audit integrity after lifecycle",f->{String id=f.approved(GOOD);f.queue(id);yes(Json.bool(f.service.audit(f.a("auditor"),0,100),"integrityValid",false));});
        test(t,"Audit cannot be read by intake actor",f->error("FORBIDDEN",()->f.service.audit(f.a("intake"),0,50)));
        test(t,"Dashboard computes counts from actual state",f->{f.intake(GOOD);f.intake("05-ubl-bad-total.xml");var d=f.service.dashboard(f.a("admin"));eq(2,Json.integer(d,"total",0));eq(1,Json.integer(Json.map(d,"counts"),"EXCEPTION",0));});
        test(t,"Credit note reduces open amount",f->{f.intake("08-ubl-credit-note.xml");eq("-119.00",Values.text(Json.map(f.service.dashboard(f.a("admin")),"openAmounts"),"EUR"));});
        test(t,"Revalidation keeps original immutable",f->{String id=f.intake(GOOD);String sha=Values.text(f.get(id),"sha256");f.service.revalidate(f.a("reviewer"),id,f.version(id));eq(sha,Values.text(f.get(id),"sha256"));});
        t.test("STRICT cannot proceed without official validator",()->{try(Fixtures f=new Fixtures(true,ValidationEngine.unavailable())){String id=f.ready(GOOD);eq("EXCEPTION",Values.text(f.get(id),"stage"));yes(Json.list(f.get(id),"blockers").contains("OFFICIAL_VALIDATION_REQUIRED"));}});
        t.test("Synthetic engine PASS releases strict workflow only in unit fixture",()->{try(Fixtures f=new Fixtures(true,Fixtures.stub("PASS"))){String id=f.ready(GOOD);eq("REVIEW",Values.text(f.get(id),"stage"));f.review(id);yes(new String(f.service.report(f.a("admin"),id)).contains("synthetic"));}});
        for(String status:List.of("FAIL","ERROR","TIMEOUT","BUSY","UNAVAILABLE"))t.test("STRICT engine "+status+" blocks approval",()->{try(Fixtures f=new Fixtures(true,Fixtures.stub(status))){String id=f.intake(GOOD);eq("EXCEPTION",Values.text(f.get(id),"stage"));yes(Json.list(f.get(id),"blockers").contains("OFFICIAL_VALIDATION_REQUIRED"));}});
        t.finish("build/test-results/workflow.xml");
    }
}
